import{z as A,x as s,o as n,c as d,q as r,j as o,D as e,d as l,s as i,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"全球金融周期","description":"","frontmatter":{"title":"全球金融周期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/global-financial-cycle.md","filePath":"econ/global-financial-cycle.md","lastUpdated":1791413859000}'),p={name:"econ/global-financial-cycle.md"};function m(D,a,c,C,u,T){const B=s("Mermaid");return n(),d("div",null,[a[2]||(a[2]=r('<h1 id="全球金融周期" tabindex="-1">全球金融周期 <a class="header-anchor" href="#全球金融周期" aria-label="Permalink to &quot;全球金融周期&quot;">​</a></h1><div class="epigraph"><p>中心国家的货币与风险偏好，经跨境信贷与资产价格共动，把外围的金融条件焊在一起——三元悖论变成两难。</p><footer>—— Rey, Dilemma not Trilemma, 2013/2015；Miranda-Agrippino and Rey；Bruno and Shin 的跨境银行</footer></div><p><a href="/econ/macroprudential">上一课</a>的杠杆外部性写在一国。资本流动把周期变成全球。本课缺口是 <strong>Rey 的全球金融周期</strong>：VIX、美元、跨境信贷共动。不重写最优 LTV 公式，不把国际货币史提前写到美元主导课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开放宏观的三元：汇率稳定、独立货币、资本流动三者不可兼得。Rey：即使汇率浮动，全球风险因子仍驱动国内信贷与资产价格，货币政策独立性被打折。Bruno–Shin：全球银行杠杆、美元融资。缺口是把 GK 的中介从封闭经济接到跨境批发融资，而不是重写 UIP 实证（量化栏）。</p><p><span class="marginnote">术语翻译：「三元悖论」说汇率稳定、独立货币政策、资本自由流动三样最多同时要两样。经典教材教浮动汇率换货币独立；Rey 的「两难」说全球金融周期把这笔交易打了折——即使汇率随行就市，你的信贷和资产价格仍被中心的收缩牵着走，「独立」只剩一半。</span></p><p><span class="marginnote">Rey, Jackson Hole 2013。Miranda-Agrippino and Rey。Bruno and Shin, <em>ReStud</em> 2015。Cetorelli and Goldberg 的全球银行内部市场。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>因子：从各国风险资产、信贷、资本流抽一个全球因子，与 VIX、美元指数相关。结构：中心国利率与风险偏好进全球银行的杠杆约束，外围信贷供给外生松紧。政策：资本流动管理作为宏观审慎的跨境工具；外汇干预；本地货币 vs 美元债（原罪）。识别：中心国货币冲击的外溢用高频或叙事，外围是接收者。</p>',9)),(n(),o(t,null,{default:e(()=>[i(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTR%5B%22%E4%B8%AD%E5%BF%83%E8%B4%A7%E5%B8%81%20%2F%20%E9%A3%8E%E9%99%A9%E5%81%8F%E5%A5%BD%22%5D%20--%3E%20LEV%5B%22%E5%85%A8%E7%90%83%E4%B8%AD%E4%BB%8B%E6%9D%A0%E6%9D%86%22%5D%0A%20%20LEV%20--%3E%20FLOW%5B%22%E8%B7%A8%E5%A2%83%E4%BF%A1%E8%B4%B7%22%5D%0A%20%20FLOW%20--%3E%20PER%5B%22%E5%A4%96%E5%9B%B4%E4%BF%A1%E8%B4%B7%E4%B8%8E%E6%88%BF%E4%BB%B7%22%5D%0A%20%20FLOAT%5B%22%E6%B5%AE%E5%8A%A8%E6%B1%87%E7%8E%87%22%5D%20--%3E%20PART%5B%22%E5%8F%AA%E9%83%A8%E5%88%86%E7%BB%9D%E7%BC%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与 HANK：外围家庭若有外汇债，全球周期直接进实际负担（债务通缩的外汇版）。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是全球净值与以美元计价的约束。美元升值恶化新兴市场企业与银行的外汇债净值，收紧 GK 约束，即使本地政策利率不动。浮动汇率缓冲贸易，不自动缓冲金融。这与 KM 的 \\(q\\) 循环同构，价格换成全球风险资产与汇率。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一家企业借了 1000 万美元债，签约时 1 美元 = 5 雷亚尔，账面 5000 万雷亚尔。美元升到 1 美元 = 5.5 雷亚尔，同一笔债变成 5500 万——什么都没做，负债凭空多出 500 万雷亚尔，净值相应缩水，抵押品价值却没跟着涨。")],-1)),(n(),o(t,null,{default:e(()=>[i(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20USD%5B%22%E7%BE%8E%E5%85%83%E5%8D%87%E5%80%BC%20%2F%20%E5%85%A8%E7%90%83%E9%A3%8E%E9%99%A9%E4%B8%8A%E5%8D%87%22%5D%20--%3E%20DEBT%5B%22%E5%A4%96%E6%B1%87%E5%80%BA%E6%9C%AC%E5%B8%81%E8%B4%9F%E6%8B%85%E5%8A%A0%E9%87%8D%22%5D%0A%20%20DEBT%20--%3E%20NW%5B%22%E4%BC%81%E4%B8%9A%E4%B8%8E%E9%93%B6%E8%A1%8C%E5%87%80%E5%80%BC%E6%81%B6%E5%8C%96%22%5D%0A%20%20NW%20--%3E%20CONSTRAINT%5B%22%E8%9E%8D%E8%B5%84%E7%BA%A6%E6%9D%9F%E6%94%B6%E7%B4%A7%22%5D%0A%20%20CONSTRAINT%20--%3E%20FIRE%5B%22%E8%A2%AB%E8%BF%AB%E5%8E%BB%E6%9D%A0%E6%9D%86%E3%80%81%E6%8A%9B%E5%94%AE%E8%B5%84%E4%BA%A7%22%5D%0A%20%20FIRE%20--%3E%20PRES%5B%22%E8%B5%84%E6%9C%AC%E5%A4%96%E6%B5%81%EF%BC%8C%E6%9C%AC%E5%B8%81%E8%BF%9B%E4%B8%80%E6%AD%A5%E8%B4%AC%E5%80%BC%22%5D%0A%20%20PRES%20--%3E%7C%22%E5%8F%8D%E9%A6%88%E7%8E%AF%E5%9B%9E%E5%88%B0%E8%B5%B7%E7%82%B9%22%7C%20USD%0A%20%20LOCAL%5B%22%E6%9C%AC%E5%9C%B0%E6%94%BF%E7%AD%96%E5%88%A9%E7%8E%87%E4%B8%8D%E5%8A%A8%22%5D%20-.-%3E%7C%22%E5%B8%AE%E4%B8%8D%E4%B8%8A%E5%BF%99%22%7C%20CONSTRAINT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：全球金融因子像海洋潮汐——不管你住在哪个岛（实行什么汇率制度），涨潮退潮同时抬压所有码头的水位。资本流动管理与宏观审慎像修防波堤：改不了潮汐时刻表，但能决定你家码头淹多深。</span></p><p>诊断性与不确定性：全球 \\(\\sigma\\) 冲击（Bloom 的国际版）同时收紧所有杠杆。新闻：中心国前瞻指引是全球新闻冲击。</p><p><span class="marginnote">Obstfeld 对三元的辩护：浮动仍给部分货币空间。本课记录争论，不假装已有唯一计量结论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 carry trade 策略。不把每一国的资本管制写成最优税率表。美元为何是中心货币，留到本单元最后一课。主权违约下一课换对象：政府而不是银行。</p><p>后课默认：浮动汇率不自动买来金融独立；全球因子经中介杠杆传导。下一课：主权不能抵押时如何借。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全球金融周期：中心风险偏好与美元驱动跨境信贷共动。</li><li>浮动汇率对金融条件只部分绝缘。</li><li>资本流动管理是跨境宏观审慎。</li><li>出处：Rey, Dilemma not Trilemma；Bruno and Shin。</li></ul>',8))])}const F=A(p,[["render",m]]);export{f as __pageData,F as default};
